{"list":[{"type":"task","center":{"x":220,"y":180},"id":"ski0qsd6qx","text":"set $$feedbackRecords","actionList":[{"formula":"// Find the related feedback records
$$backendIDs = record\findRelatedMany('CInsight', id, 'feedbackDatas', 9999, 'createdAt', 'desc');
// Find the related community meeting records
$$meetingBackendIDs = record\findRelatedMany('CInsight', id, 'communityMeetingDatas', 9999, 'createdAt', 'desc');
autoInsightStatus = 'processing';
// Initialize loop variables
$i = 0;
$feedbackRecords = list();
$count = array\length($$backendIDs);

// Loop through feedback records
while($i < $count) {
  $$backendID = array\at($$backendIDs, $i);

  // Fetch feedback description early to check if it's empty
  $feedbackDescription = record\attribute('CFeedbackData', $$backendID, 'feedbackDescription');

  // Skip records without analyzable text
  if ($feedbackDescription != null && $feedbackDescription != '') {
    $urlID = $$backendID;
    $feedbackID = record\attribute('CFeedbackData', $$backendID, 'feedbackFormID');
    $codingLevel1 = record\attribute('CFeedbackData', $$backendID, 'codingLevel1Name');
    $codingLevel2 = record\attribute('CFeedbackData', $$backendID, 'codingLevel2Name');
    $codingLevel3 = record\attribute('CFeedbackData', $$backendID, 'codingLevel3Name');
    $createdAt = record\attribute('CFeedbackData', $$backendID, 'createdAt');

    ifThen($feedbackID == null, $feedbackID = '');
    ifThen($urlID == null, $urlID = '');
    ifThen($createdAt == null, $createdAt = '');

    $metadata = object\create();
    $metadata['created'] = $createdAt;
    $metadata['coding_level_1'] = $codingLevel1;
    $metadata['coding_level_2'] = $codingLevel2;
    $metadata['coding_level_3'] = $codingLevel3;

    $feedbackRecord = object\create();
    $feedbackRecord['record_type'] = 'feedback';
    $feedbackRecord['content'] = $feedbackDescription;
    $feedbackRecord['id'] = $feedbackID;
    $feedbackRecord['url_id'] = $urlID;
    $feedbackRecord['metadata'] = $metadata;

    $feedbackRecords = array\push($feedbackRecords, $feedbackRecord);
  }

  $i = $i + 1;
}

// Loop through community meeting records
$i = 0;
$meetingCount = array\length($$meetingBackendIDs);
while($i < $meetingCount) {
  $$meetingBackendID = array\at($$meetingBackendIDs, $i);

  $meetingNotes = record\attribute('CCommunityMeetingData', $$meetingBackendID, 'meetingNotes');

  // Skip records without analyzable text
  if ($meetingNotes != null && $meetingNotes != '') {
    $meetingID = record\attribute('CCommunityMeetingData', $$meetingBackendID, 'meetingID');
    $createdAt = record\attribute('CCommunityMeetingData', $$meetingBackendID, 'createdAt');
    $dateOfMeeting = record\attribute('CCommunityMeetingData', $$meetingBackendID, 'dateOfMeeting');
    $methodOfCollection = record\attribute('CCommunityMeetingData', $$meetingBackendID, 'methodOfCollection');
    $format = record\attribute('CCommunityMeetingData', $$meetingBackendID, 'format');
    $project = record\attribute('CCommunityMeetingData', $$meetingBackendID, 'project');
    $location = record\attribute('CCommunityMeetingData', $$meetingBackendID, 'location');
    $ageGroup = record\attribute('CCommunityMeetingData', $$meetingBackendID, 'ageGroup');
    $gender = record\attribute('CCommunityMeetingData', $$meetingBackendID, 'gender');
    $groupSize = record\attribute('CCommunityMeetingData', $$meetingBackendID, 'groupSize');

    ifThen($meetingNotes == null, $meetingNotes = '');
    ifThen($meetingID == null, $meetingID = '');
    ifThen($meetingID != null, $meetingID = string\concatenate($meetingID, ''));
    ifThen($createdAt == null, $createdAt = '');
    ifThen($dateOfMeeting != null, $dateOfMeeting = string\concatenate($dateOfMeeting, ''));
    ifThen($groupSize != null, $groupSize = string\concatenate($groupSize, ''));

    $metadata = object\create();
    $metadata['created'] = $createdAt;
    $metadata['dateOfMeeting'] = $dateOfMeeting;
    $metadata['methodOfCollection'] = $methodOfCollection;
    $metadata['format'] = $format;
    $metadata['project'] = $project;
    $metadata['location'] = $location;
    $metadata['ageGroup'] = $ageGroup;
    $metadata['gender'] = $gender;
    $metadata['groupSize'] = $groupSize;

    $meetingRecord = object\create();
    $meetingRecord['record_type'] = 'community_meeting';
    $meetingRecord['id'] = $meetingID;
    $meetingRecord['meetingNotes'] = $meetingNotes;
    $meetingRecord['metadata'] = $metadata;
    $meetingRecord['url_id'] = $$meetingBackendID;

    $feedbackRecords = array\push($feedbackRecords, $meetingRecord);
  }

  $i = $i + 1;
}

// json\encode escapes line breaks, quotes and backslashes safely.
$$feedbackRecords = $feedbackRecords;","cid":0,"id":"f21zm1kmdv","type":"executeFormula"}],"description":null},{"type":"task","center":{"x":360,"y":180},"id":"9levq1av1e","text":"select $fullEndpoint","actionList":[{"formula":"$$selectedMethod = record\attribute('CInsight', id, 'method');
$url= ext\appSecret\get('QFA_API_BASE_URL');

if ($$selectedMethod == "summarize_aggregate") {$$endpoint = "/v1/summarize-bulk";}
else if ($$selectedMethod == "analyze") {$$endpoint = "/v1/analyze-bulk";}
else {$$endpoint = "/v1/summarize-bulk";}

// Currently hard-coded until upgraded to espo 9.2.3+
$fullEndpoint = string\concatenate($url, $$endpoint);
","cid":0,"id":"9xjb2unsg3","type":"executeFormula"}],"description":null},{"type":"task","center":{"x":500,"y":180},"id":"rzhpnsh7eu","text":"combine $motherPayload","actionList":[{"formula":"// This creates a "mother" payload that can be used to hit any of the inference routes

$outputLanguage = record\attribute('CInsight', id, 'outputLanguage');
$prompt = record\attribute('CInsight', id, 'freeTextPrompt');
$espoFeedbackBaseUrl = ext\appSecret\get('ESPO_FEEDBACK_BASE_URL');

$payload = object\create();
$payload['feedback_records'] = $$feedbackRecords;
$payload['prompt'] = $prompt;
$payload['espo_feedback_base_url'] = $espoFeedbackBaseUrl;
$payload['output_language'] = $outputLanguage;
$payload['selected_method'] = $$selectedMethod;
$payload['endpoint'] = $$endpoint;

$motherPayload = json\encode($payload);","cid":0,"id":"iakgn85ltq","type":"executeFormula"}],"description":null},{"type":"task","center":{"x":640,"y":180},"id":"wkr4x6yr9y","text":"POST request, set modelResponse","actionList":[{"requestType":"POST","contentType":"application/json","content":"{}","requestUrl":"{$$fullEndpoint}","headers":["Authorization: Bearer {#secrets.QFA_API_KEY}"],"contentVariable":"$motherPayload","cid":0,"id":"kdp8p1i3fn","type":"sendRequest"},{"formula":"// This assigns the bulk response fields to the Insight attributes.

$response = $_lastHttpResponseBody;

modelResponse = json\retrieve($response, 'pretty_output');
qualityText = json\retrieve($response, 'quality_text');
qualityScore = json\retrieve($response, 'quality_score');
requestID = json\retrieve($response, 'request_id');
title = json\retrieve($response, 'title');
autoInsightStatus = 'completed';","cid":1,"id":"gtautkujwr","type":"executeFormula"}],"description":null,"isolateVariables":false},{"type":"eventEnd","center":{"x":780,"y":180},"id":"d0hc7g2kh6"},{"startId":"ski0qsd6qx","endId":"9levq1av1e","startDirection":"r","id":"g3x1k6f9lc","type":"flow"},{"startId":"9levq1av1e","endId":"rzhpnsh7eu","startDirection":"r","id":"fce1ihrzqb","type":"flow"},{"startId":"rzhpnsh7eu","endId":"wkr4x6yr9y","startDirection":"r","id":"v0wqwentos","type":"flow"},{"startId":"wkr4x6yr9y","endId":"d0hc7g2kh6","startDirection":"r","id":"4i4kjyvuay","type":"flow"},{"type":"eventStartConditional","center":{"x":60,"y":180},"triggerType":"afterRecordCreated","isInterrupting":false,"id":"d9dcscokfu","text":"When insight is saved","conditionsAll":[],"conditionsAny":[],"conditionsFormula":null,"description":null},{"startId":"d9dcscokfu","endId":"ski0qsd6qx","startDirection":"r","id":"pu4ayxgwp9","type":"flow"},{"type":"eventIntermediateErrorBoundary","attachedToId":"wkr4x6yr9y","errorCode":null,"attachPosition":"bl1","center":{"x":620,"y":215},"id":"7te9muws0u"},{"type":"task","center":{"x":580,"y":320},"id":"97z1jpm1m3","text":"error notification","description":null,"actionList":[{"formula":"autoInsightErrorCode = bpm\caughtErrorCode();
autoInsightErrorMessage = bpm\caughtErrorMessage();
autoInsightStatus = 'failed';","cid":0,"id":"y4tpm1z657","type":"executeFormula"}]},{"startId":"7te9muws0u","endId":"97z1jpm1m3","startDirection":"l","id":"uk5eocp9ah","type":"flow"},{"startId":"97z1jpm1m3","endId":"d0hc7g2kh6","startDirection":"r","id":"iwlxbrj67z","type":"flow"}],"createdEntitiesData":{}}
